SELECT
  (SELECT COUNT(*) FROM `brands` WHERE `name` IN ('Te Amo','Miami Cigar & Co.')) = 2 AS deux_fiches,
  (SELECT COUNT(*) FROM `brands` WHERE `name` = 'Te-Amo') = 0 AS aucun_doublon,
  (SELECT `history` LIKE '%1963%' AND `history` LIKE '%1966%' FROM `brands` WHERE `name` = 'Te Amo') AS te_amo_ecart_ecrit,
  (SELECT `brands` LIKE '%"Te Amo"%' AND `brands` NOT LIKE '%"Te-Amo"%' FROM `producer_countries` WHERE `id` = 'mexico') AS mexico_annonce,
  (SELECT `brands` LIKE '%Miami Cigar%' FROM `producer_countries` WHERE `id` = 'nicaragua') AS nicaragua_annonce,
  (SELECT SUM(CHAR_LENGTH(`detail`) >= 255) = 0 FROM `moderation_log` WHERE `acteur_nom` = 'migration 210') AS journal_non_tronque;
SELECT COUNT(*) AS marques, SUM(TRIM(COALESCE(`source`,'')) = '') AS sans_source FROM `brands`;
